mapper.select:
SELECT space_id AS id, COUNT(*) AS totalNum FROM bbx_material WHERE space_id IS NOT NULL AND deleted = 1
and tenant_id =#{tenantId}
GROUP BY space_id

SELECT CASE WHEN material_type = 1 THEN '器材' WHEN material_type = 2 THEN '耗材-备品' WHEN material_type = 3 THEN '耗材-备件' ELSE '其他类型' END AS name, material_type as code, SUM(GREATEST(stock_quantity, 0)) AS totalNum FROM bbx_material where deleted = 1
and tenant_id =#{tenantId}
GROUP BY material_type ORDER BY totalNum desc

SELECT CASE stock_status WHEN 1 THEN '库存充足' WHEN 2 THEN '库存不足' WHEN 3 THEN '库存缺货' ELSE '其他类型' END AS name, COUNT(*) AS totalNum FROM bbx_material WHERE deleted = 1
and tenant_id =#{tenantId}
GROUP BY stock_status
